{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "The closest transferred analogue, [18F]6FPWAY, showed rapid brain uptake in monkeys with a maximal uptake of 4.33% of injected dose and was classified as BBB-permeable; the query shares the same methoxyphenylpiperazine and pyridylamide core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "WAY-100635, the direct cyclohexyl analogue of the query, showed good maximal brain uptake of 5.0% in cynomolgus monkeys by PET, demonstrating meaningful CNS access despite being a P-gp substrate.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "The closely related 18F-mefway tracer penetrated the human brain rapidly with a peak SUV of 1.7, confirming that this scaffold class achieves adequate CNS exposure in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "The fluorinated analogue FCWAY is BBB-permeable and used for 5-HT1A PET imaging in rodents and humans, further supporting meaningful brain access for this structural family.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a close structural analogue of WAY-100635 and related 5-HT1A PET tracers that consistently show rapid, meaningful brain uptake across species despite some P-gp efflux liability; therefore the prediction is pass.",
  "evidence_gaps": [
    "No direct experimental record exists for the exact norbornane-containing query molecule.",
    "The magnitude of any P-gp efflux for the query is not directly quantified, but the close analogues still achieve adequate CNS exposure."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

